import org.jgrapht.graph.DefaultDirectedWeightedGraph;
import org.jgrapht.graph.DefaultWeightedEdge;
import org.jgrapht.alg.flow.DinicMFImpl;
import org.jgrapht.alg.flow.MaximumFlowAlgorithm;

import java.util.Set;

public class BipartiteMatchingWithJGraphT {

    public static void main(String[] args) {
        // 1. Create a directed weighted graph
        DefaultDirectedWeightedGraph<String, DefaultWeightedEdge> graph =
            new DefaultDirectedWeightedGraph<>(DefaultWeightedEdge.class);

        // 2. Add source and sink nodes
        String source = "S";
        String sink = "T";
        graph.addVertex(source);
        graph.addVertex(sink);

        // 3. Add developer and project nodes
        String[] developers = {"D1", "D2", "D3"};
        String[] projects = {"P1", "P2", "P3"};

        for (String dev : developers) {
            graph.addVertex(dev);
            graph.addEdge(source, dev); // Source to developer, capacity 1
            graph.setEdgeWeight(graph.getEdge(source, dev), 1.0);
        }

        for (String proj : projects) {
            graph.addVertex(proj);
            graph.addEdge(proj, sink); // Project to sink, capacity 1
            graph.setEdgeWeight(graph.getEdge(proj, sink), 1.0);
        }

        // 4. Define compatibility (developer to project edges)
        // D1 can do P1, P2
        graph.addEdge("D1", "P1"); graph.setEdgeWeight(graph.getEdge("D1", "P1"), 1.0);
        graph.addEdge("D1", "P2"); graph.setEdgeWeight(graph.getEdge("D1", "P2"), 1.0);
        // D2 can do P2, P3
        graph.addEdge("D2", "P2"); graph.setEdgeWeight(graph.getEdge("D2", "P2"), 1.0);
        graph.addEdge("D2", "P3"); graph.setEdgeWeight(graph.getEdge("D2", "P3"), 1.0);
